def _resolve_metrics_endpoint(settings: Settings) -> tuple[Optional[str], bool]:
    """
    Resolve the OTLP metrics endpoint and whether it points at Prefect Cloud.

    Resolution order:
        1. ``OTEL_EXPORTER_OTLP_METRICS_ENDPOINT`` (used verbatim, never treated as cloud)
        2. ``OTEL_EXPORTER_OTLP_ENDPOINT`` with ``/v1/metrics`` appended (never treated as cloud)
        3. The Prefect API URL when connected to Prefect Cloud (treated as cloud)

    Returns:
        A tuple of ``(endpoint_url, is_cloud)``. ``endpoint_url`` is ``None`` when no
        endpoint can be resolved, in which case ``is_cloud`` is ``False``.
    """
    metrics_endpoint = os.environ.get("OTEL_EXPORTER_OTLP_METRICS_ENDPOINT")
    if metrics_endpoint:
        return metrics_endpoint, False

    base_endpoint = os.environ.get("OTEL_EXPORTER_OTLP_ENDPOINT")
    if base_endpoint:
        return f"{base_endpoint.rstrip('/')}/v1/metrics", False

    if settings.connected_to_cloud and settings.api.url:
        return f"{settings.api.url.rstrip('/')}/telemetry/v1/metrics", True

    return None, False


class RunMetrics:
    """
    A context manager that collects and exports system resource metrics (such as
    CPU and memory usage) while a flow run is executing.

    On entry, a ``SystemMetricsInstrumentor`` is configured with a ``MeterProvider``
    backed by an ``OTLPMetricExporter`` and instrumentation is started. On exit,
    instrumentation is stopped and the meter provider is shut down.

    The context manager degrades to a no-op (without raising) when:
        - resource metrics are disabled via settings,
        - no metrics endpoint can be resolved,
        - the required OpenTelemetry libraries cannot be imported, or
        - any exception is raised while setting up instrumentation.
    """

    def __init__(self, flow_run: "FlowRun", flow: "Flow[Any, Any]"):
        self.flow_run = flow_run
        self.flow = flow
        self._instrumentor: Any = None
        self._meter_provider: Any = None

    def _setup(self) -> None:
        settings = get_current_settings()
        if not settings.telemetry.enable_resource_metrics:
            return

        endpoint, is_cloud = _resolve_metrics_endpoint(settings)
        if endpoint is None:
            return

        try:
            from opentelemetry.exporter.otlp.proto.http.metric_exporter import (
                OTLPMetricExporter,
            )
            from opentelemetry.instrumentation.system_metrics import (
                SystemMetricsInstrumentor,
            )
            from opentelemetry.sdk.metrics import MeterProvider
            from opentelemetry.sdk.metrics.export import PeriodicExportingMetricReader
            from opentelemetry.sdk.resources import Resource
        except ImportError:
            logger.debug(
                "Unable to import OpenTelemetry libraries required for resource"
                " metrics collection; skipping.",
            )
            return

        if is_cloud:
            assert settings.api.key is not None
            exporter = OTLPMetricExporter(
                endpoint=endpoint,
                headers={
                    "Authorization": f"Bearer {settings.api.key.get_secret_value()}"
                },
            )
        else:
            exporter = OTLPMetricExporter(endpoint=endpoint)

        reader = PeriodicExportingMetricReader(
            exporter,
            export_interval_millis=settings.telemetry.resource_metrics_interval_seconds
            * 1000,
        )

        resource = Resource.create(
            {
                "service.name": "prefect",
                "prefect.flow-run.id": str(getattr(self.flow_run, "id", "")),
                "prefect.flow-run.name": str(getattr(self.flow_run, "name", "")),
                "prefect.flow.name": str(getattr(self.flow, "name", "")),
            }
        )

        meter_provider = MeterProvider(metric_readers=[reader], resource=resource)
        instrumentor = SystemMetricsInstrumentor()
        instrumentor.instrument(meter_provider=meter_provider)

        self._instrumentor = instrumentor
        self._meter_provider = meter_provider

    def __enter__(self) -> "RunMetrics":
        try:
            self._setup()
        except Exception:
            logger.debug(
                "Failed to set up resource metrics collection; continuing without it.",
                exc_info=True,
            )
            self._instrumentor = None
            self._meter_provider = None
        return self

    def __exit__(self, *exc_info: Any) -> None:
        if self._instrumentor is not None:
            try:
                self._instrumentor.uninstrument()
            except Exception:
                logger.debug(
                    "Failed to uninstrument resource metrics collection.",
                    exc_info=True,
                )
        if self._meter_provider is not None:
            try:
                self._meter_provider.shutdown()
            except Exception:
                logger.debug(
                    "Failed to shut down resource metrics meter provider.",
                    exc_info=True,
                )
        self._instrumentor = None
        self._meter_provider = None
